package ktanesolver.module.modded.regular.giantsdrink;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class GiantsDrinkSolverTest{@Test void followsThePrimarySilverHighGemBranch(){BombEntity b=new BombEntity();GiantsDrinkInput.Goblet l=new GiantsDrinkInput.Goblet("silver","diamond","red",1,10,"bowl"),r=new GiantsDrinkInput.Goblet("gold","ruby","blue",2,5,"bowl");@SuppressWarnings("unchecked")GiantsDrinkOutput o=((SolveSuccess<GiantsDrinkOutput>)new GiantsDrinkSolver().solve(new RoundEntity(),b,new ModuleEntity(),new GiantsDrinkInput(l,r))).output();assertThat(o.safeGoblet()).isEqualTo("left");assertThat(o.path()).containsExactly(1,2,3,4,6);assertThat(o.command()).isEqualTo("left");}}
